#!/usr/bin/env bash
# Create Secret besu-nodekey (key `nodekey`, 32 random bytes as hex) INSIDE the party namespace; the value is generated by openssl on this host,
# piped to kubectl, never written to a file, never printed (final-design/zeto/PLAN.md S3: "generated inside the ns, never leaves it").
#   KUBECONFIG=<party kubeconfig> ./nodekey.sh <bi|bank-a|bank-b|bank-c>
set -euo pipefail
party="${1:?usage: nodekey.sh <bi|bank-a|bank-b|bank-c>}"
case "$party" in bi|bank-a|bank-b|bank-c) ;; *) echo "nodekey.sh: unknown party '$party'" >&2; exit 2 ;; esac
command -v openssl >/dev/null || { echo "nodekey.sh: openssl missing" >&2; exit 2; }
ns="rd-zeto-$party"
kubectl -n "$ns" create secret generic besu-nodekey --from-file=nodekey=<(openssl rand -hex 32)
echo "nodekey.sh: Secret besu-nodekey is in $ns (value not shown); next: render.sh nodeinfo $party"
